// WideOption configures a contract run.
type WideOption func(*wideConfig)

// WideSubject declares an implementation to hold to the contract.
//
// Repeat it for every implementation that claims to satisfy the interface — an
// in-memory one, the one backed by a database, the one behind a network. Every
// check and every option is stated once and runs against all of them, which is
// what a conformance suite is for.
func WideSubject(name string, factory func() multireturn.Wide) WideOption {
	return func(c *wideConfig) {
		c.subjects = append(c.subjects, namedWideSubject{name, factory})
	}
}

// WideWithoutDouble declines the second run through WideStub.
